def exact(actual, expected, label):
    if json.dumps(actual, sort_keys=True, default=lambda b: ["bytes", b.hex()]) != json.dumps(expected, sort_keys=True, default=lambda b: ["bytes", b.hex()]):
        raise ValueError(label)

def sha(content):
    return hashlib.sha256(content).hexdigest()

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or rel.startswith('/') or any(x in ('', '.', '..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p = root / safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute() != p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('unsafe file ' + rel)
    return p.read_bytes()

def validate_confirmation(c, receipt):
    exact(sha((json.dumps(c, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()), CONFIRMATION_SHA256, 'external326 confirmation')
    exact(sorted(receipt), ['encoding','original_display_sha256','original_display_size_bytes','text'], 'receipt fields')
    exact(receipt['encoding'], 'utf8-json-text', 'receipt encoding'); raw=receipt['text'].encode()
    exact(sha(raw), RECEIPT_SHA256, 'original326 digest'); exact(len(raw), 247354, 'original326 length')
    exact(receipt['original_display_sha256'], RECEIPT_SHA256, 'receipt metadata digest'); exact(receipt['original_display_size_bytes'], 247354, 'receipt metadata size')
    lines=receipt['text'].splitlines(); exact(sum(x.startswith('PASS: ') for x in lines),3404,'complete3404 return')
    exact(lines.count('Result: PASS (3404 passes, 0 failures)'),1,'full3404 summary')
    log='aae7c8b (HEAD -> main, origin/main, origin/HEAD) Phase 1 step 326: review finite failure model and independent conformance plan'
    exact(lines.count(log),2,'matching326 HEAD origin')
    if '[main aae7c8b]' not in receipt['text'] or '0c5caa7..aae7c8b  main -> main' not in receipt['text']: raise ValueError('missing326 commit/push')
    return True

def verify_history(root, policy):
    binding = policy['baseline_sha256_bindings']
    serialized = (json.dumps(binding, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()
    exact(sha(serialized),BASELINE_JSON_SHA256,'exact accepted1521 manifest')
    exact(len(binding),1521,'accepted1521 file count')
    history = {}
    for rel,digest in binding.items():
        content = safe_file(root,rel)
        if rel == 'CHANGELOG.md':
            prefix = CHANGELOG_PREFIX.encode()
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            exact(content[:len(prefix)],prefix,'new CHANGELOG prefix')
            content = content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel] = content
    return history

def validate_design(design, prior, frozen, history):
    exact(design,DESIGN_SPEC,'exact scoped effects obligations rights crossclosure')
    exact(sha((json.dumps(prior,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),PRIOR_DESIGN_SHA256,'exact326 finite model/conformance plan')
    for step,binding in design['previous_design_bindings'].items(): exact(sha(history[binding['path']]),binding['sha256'],'exact prior design '+step)
    exact(design['seven_requirements_bindings'],frozen['seven_review_bindings'],'seven frozen requirements')
    exact(design['preserved_cross_obligations'],frozen['proof_obligations'],'ten frozen cross obligations')
    for binding in design['seven_requirements_bindings']:
        for role in ['policy','review']: exact(sha(history[binding[role+'_path']]),binding[role+'_sha256'],'capability source '+binding['capability']+'/'+role)
    for item in design['future_proof_inventory']:
        source=json.loads(history[item['source_design_path']]); rows={row['id']:row for row in source['future_proof_obligations']}
        exact(item['source_proof'],rows[item['source_proof']['id']],'immutable future proof '+item['qualified_id'])
        exact(item['source_design_sha256'],sha(history[item['source_design_path']]),'future proof source SHA')
    graph=json.loads(history[design['whole_graph_binding']['path']])
    exact([r['effect_node'] for r in design['crossclosure_matrix']],[r['id'] for r in graph['catalogue_nodes']],'all30 effect nodes')
    exact(design['catalogue_edges'],graph['catalogue_edges'],'every designed graph edge retained')
    exact(design['conformance_plan_binding'],dict(path=design['previous_design_bindings']['326']['path'],sha256=PRIOR_DESIGN_SHA256,case_count=52,actual_runs=0),'52 required-not-run entries preserved')
    return True

def validate_tables(roadmap, obligations):
    exact(sha(roadmap),TABLE_HASHES[0],'exact typed roadmap')
    exact(sha(obligations),TABLE_HASHES[1],'exact obligation coverage table')
    return True

def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode('ascii')

def unique_pairs(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON field')
        result[key]=value
    return result


def evaluate_private_rights_window(value):
    exact(sorted(value),['conditions','grant_state','origin','scope','window'],'rights-window fields')
    exact(value['origin'],'synthetic-private-fixture','rights-window origin')
    exact(value['scope'],'actor-specific-rights-window-contract-only','rights-window scope')
    exact(sorted(value['conditions']),sorted(RIGHT_GATE_KEYS),'rights-window gate names')
    if any(type(x) is not bool for x in value['conditions'].values()): raise ValueError('typed rights-window gates')
    if type(value['window']) is not str or value['window'] not in WINDOW_GATES: raise ValueError('unknown rights window')
    if type(value['grant_state']) is not str or value['grant_state'] not in ['known-unused','known-consumed','unknown']: raise ValueError('typed original grant state')
    window=value['window']; eligible=all(value['conditions'][k] for k in WINDOW_GATES[window])
    if window=='admission': eligible=eligible and value['grant_state']=='known-unused'
    elif window in ['launch','bootstrap','service','forward','recovery']: eligible=eligible and value['grant_state']=='known-consumed'
    elif window=='forbidden': eligible=False
    return dict(model_window_contract_eligible=eligible,actual_rights_valid=False,actual_target_effect_authorized=False,
        actual_operational_conformance=False,actual_new_grant_authorized=False,
        same_original_attempt_required=window in ['launch','bootstrap','service','forward','recovery'],
        new_target_grant_from_publication=False,forward_renewal_from_recovery=False)

def evaluate_private_crossclosure(value):
    exact(sorted(value),['claim','conditions','origin','scope','vectors'],'crossclosure fields')
    exact(value['origin'],'synthetic-private-fixture','crossclosure origin')
    exact(value['scope'],'complete-scoped-evidence-index-contract-only','crossclosure scope')
    if type(value['claim']) is not str or value['claim'] not in ['repository-design-crossclosure','actual-runtime-readiness','global-host-absence','new-runtime-authorization']: raise ValueError('typed crossclosure claim')
    exact(sorted(value['conditions']),sorted(CLOSURE_GATES),'crossclosure gate names')
    if any(type(x) is not bool for x in value['conditions'].values()): raise ValueError('typed crossclosure gates')
    exact(sorted(value['vectors']),sorted(VECTOR_IDS),'complete vector domains')
    for domain,ids in VECTOR_IDS.items():
        vector=value['vectors'][domain]
        if type(vector) is not dict: raise ValueError('typed complete vector '+domain)
        exact(sorted(vector),sorted(ids),'complete vector keys '+domain)
        if any(type(x) is not bool for x in vector.values()): raise ValueError('typed vector proof '+domain)
    index_complete=all(value['conditions'].values()) and all(all(v.values()) for v in value['vectors'].values())
    return dict(model_scoped_index_complete=index_complete,
        model_repository_design_claim_eligible=index_complete and value['claim']=='repository-design-crossclosure',
        actual_effects_proven=False,actual_obligations_closed=False,actual_rights_valid=False,
        actual_platform_conformance=False,actual_runtime_readiness=False,actual_global_host_absence=False,
        actual_new_runtime_authorization=False,actual_strong_safe_pause_confirmed=False,
        new_grant_authorized=False,operational_proof_waived=False,unobserved_state_is_absent=False)











def run_historical(history):
    with tempfile.TemporaryDirectory(prefix='step327-exact326-') as directory:
        snapshot = Path(directory)/'slack-update'
        for rel,content in history.items():
            p = snapshot/safe_relative(rel); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(content)
        result = subprocess.run(['bash',str(snapshot/'tests/reference'/('test-'+PRIOR+'-harness.sh'))],capture_output=True)
        lines = result.stdout.decode().splitlines()
        if result.returncode or lines.count('Result: PASS (3404 passes, 0 failures)')!=1 or sum(x.startswith('PASS: ') for x in lines)!=3404:
            sys.stderr.buffer.write(result.stdout+result.stderr)
            raise ValueError('full exact3404 predecessor acceptance failed')
        return result.stdout

def main(root,out):
    if not root.is_dir() or root.absolute()!=root.resolve(): raise ValueError('unsafe repository root')
    for rel,digest in OWN_HASHES.items(): exact(sha(safe_file(root,rel)),digest,'changed327 input '+rel)
    fixture=root/FIXTURE; load=lambda suffix:json.loads((fixture/(BASE+suffix)).read_bytes())
    policy,design=load('-policy.json'),load('-design.json'); history=verify_history(root,policy)
    frozen=json.loads(history[FIXTURE+'/'+REQUIREMENTS_BASE+'-freeze.json']); prior=json.loads(history[FIXTURE+'/'+PRIOR+'-design.json'])
    validate_design(design,prior,frozen,history); validate_confirmation(load('-checkpoint-confirmation.json'),load('-step326-user-acceptance.json'))
    validate_tables(*[(fixture/(BASE+s)).read_bytes() for s in ['-effects-obligations-rights-crossclosure.tsv','-proofs-and-authority-windows.tsv']])
    payloads={BASE+s:(fixture/(BASE+s)).read_bytes() for s in SUFFIXES}; log_name=BASE+'-predecessor-test.log'
    if not out.is_dir() or out.absolute()!=out.resolve(): raise ValueError('output must exist without symlink ancestors')
    if any((out/name).exists() or (out/name).is_symlink() for name in list(payloads)+[log_name]): raise ValueError('occupied output; no overwrite')
    payloads[log_name]=run_historical(history); exact(verify_history(root,policy),history,'history changed during validation')
    for rel,digest in OWN_HASHES.items(): exact(sha(safe_file(root,rel)),digest,'327 input changed during validation')
    created=[]
    try:
        for name,content in payloads.items():
            with (out/name).open('xb') as stream: created.append(out/name); stream.write(content)
    except BaseException:
        for p in reversed(created): p.unlink()
        raise
    print('exact_step326_acceptance\tPASS (3404 passes, 0 failures)')
    print('step327_scoped_crossclosure_review_status\tPASS')
    print('actual_effects_obligations_rights_or_conformance_proven\tno')
    print('actual_dispatch_or_publication_authorized\tno'); print('operational_readiness\tno'); print('strong_safe_pause\tno')
    print('last_confirmed_strong_safe_pause_step\t318'); print('next_stage_authorized\tno')

if __name__ == '__main__':
    try: main(Path(sys.argv[1]).absolute(),Path(sys.argv[2]).absolute())
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print('ERROR: '+str(exc),file=sys.stderr);sys.exit(1)
